using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading;using System.Diagnostics;
public static class ScanAccelerationTests {
 [System.Runtime.InteropServices.DllImport("kernel32.dll",SetLastError=true)]static extern bool DeviceIoControl(Microsoft.Win32.SafeHandles.SafeFileHandle h,uint code,IntPtr input,uint inputSize,IntPtr output,uint outputSize,out uint returned,IntPtr overlapped);
 static int failed,passed;static void Check(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.GetBaseException().Message);}}
 static IEnumerable<FileEntry> Read(string path,CancellationToken token){var t=typeof(StorageScanJob).Assembly.GetType("LocalStorageScan");if(t==null)throw new Exception("native bulk scan is not implemented");return (IEnumerable<FileEntry>)t.GetMethod("Enumerate",BindingFlags.Public|BindingFlags.Static).Invoke(null,new object[]{path,token});}
 static void Must(bool yes,string why){if(!yes)throw new Exception(why);}
 public static int Main(){string root=Path.Combine(Path.GetTempPath(),"asterhub-accel-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
  Directory.CreateDirectory(Path.Combine(root,"空目录"));File.WriteAllText(Path.Combine(root,"中文 space.log"),"abcdef");File.WriteAllText(Path.Combine(root,"zero.bin"),"");DateTime stamp=new DateTime(2025,3,4,5,6,8,DateTimeKind.Utc);File.SetLastWriteTimeUtc(Path.Combine(root,"中文 space.log"),stamp);
  Check("native enumeration preserves Unicode, sizes, UTC timestamps and directories",()=>{var list=Read(root,CancellationToken.None).ToList();Must(list.Count==3,"wrong count");var f=list.Single(x=>x.Name=="中文 space.log");Must(f.Size==6&&!f.IsDirectory&&f.FullPath==Path.Combine(root,f.Name),"wrong metadata");Must(f.Modified.ToUniversalTime()==stamp,"wrong timestamp");Must(list.Single(x=>x.Name=="空目录").IsDirectory,"directory lost");});
  Check("empty directory yields no dot entries",()=>Must(!Read(Path.Combine(root,"空目录"),CancellationToken.None).Any(),"dot entries included"));
  Check("cancelled enumeration throws without reading entries",()=>{var c=new CancellationTokenSource();c.Cancel();try{Read(root,c.Token).ToList();throw new Exception("cancellation ignored");}catch(OperationCanceledException){}});
  Check("disposing partial enumeration closes native handles",()=>{Read(root,CancellationToken.None).Take(1).ToArray();int before=Process.GetCurrentProcess().HandleCount;for(int i=0;i<300;i++)Read(root,CancellationToken.None).Take(1).ToArray();GC.Collect();GC.WaitForPendingFinalizers();Must(Process.GetCurrentProcess().HandleCount-before<8,"find handles leaked");});
  Check("missing root fails instead of returning successful empty scan",()=>{try{Read(Path.Combine(root,"absent"),CancellationToken.None).ToList();throw new Exception("missing root accepted");}catch(DirectoryNotFoundException){}catch(System.ComponentModel.Win32Exception){}});

  Check("size high DWORD preserves files larger than 4GiB without reading content",()=>{string dir=Path.Combine(root,"sparse");Directory.CreateDirectory(dir);string file=Path.Combine(dir,"large.bin");using(var h=new FileStream(file,FileMode.Create,FileAccess.Write,FileShare.Read)){uint returned;if(!DeviceIoControl(h.SafeFileHandle,0x000900C4,IntPtr.Zero,0,IntPtr.Zero,0,out returned,IntPtr.Zero))throw new Exception("cannot create sparse fixture");h.SetLength(5L*1024*1024*1024+37);}Must(Read(dir,CancellationToken.None).Single().Size==5L*1024*1024*1024+37,"high DWORD lost");File.Delete(file);Directory.Delete(dir);});
  Check("cancellation between native entries stops and closes handle",()=>{var c=new CancellationTokenSource();using(var e=Read(root,c.Token).GetEnumerator()){Must(e.MoveNext(),"fixture empty");c.Cancel();try{e.MoveNext();throw new Exception("late cancellation ignored");}catch(OperationCanceledException){}}});
  Check("read-only metadata is retained",()=>{string file=Path.Combine(root,"zero.bin");File.SetAttributes(file,FileAttributes.ReadOnly);try{Must(Read(root,CancellationToken.None).Single(x=>x.Name=="zero.bin").Permissions=="只读","read-only lost");}finally{File.SetAttributes(file,FileAttributes.Normal);}});
  Check("real StorageScanJob keeps paths, totals and empty directories",()=>{var job=new StorageScanJob(new Server{IsLocal=true},root);job.Run().GetAwaiter().GetResult();Must(job.Status=="ready",job.Error);Must(job.Result.Node("0").Bytes==6&&job.Result.Node("0").Count==2,"wrong aggregate");Must(!job.Result.Partial,"unexpected partial");Must(job.Result.Nodes.Values.Any(n=>n.Name=="空目录"),"empty directory lost");});
 }finally{if(Path.GetDirectoryName(root)!=Path.GetTempPath().TrimEnd('\\'))throw new Exception("unsafe fixture path");Directory.Delete(root,true);}Console.WriteLine(passed+" passed, "+failed+" failed");return failed==0?0:1;}
}
